#[summary("과제 구현")]
mod tasks {
    spec fn nonempty(x: &[i64]) -> bool { x.len() >= 1 }

    spec fn valid_at(x: &[i64], r: usize) -> bool { r < x.len() && x[r] >= x[0] }

    #[effects(pure)]
    #[uses(nonempty, valid_at)]
    fn myfun1(x: &[i64]) -> (r: usize)
        requires nonempty(x),
        ensures valid_at(x, r),
    {
        let mut m: usize = 0;
        let mut i: usize = 1;
        while i < x.len()
            invariant 1 <= i, m < i, i <= x.len(), x[m] >= x[0],
            decreases x.len() - i,
        {
            if x[i] > x[m] {
                m = i;
            }
            i = i + 1;
        }
        m
    }
}
